TAX_RATE = 0.08


def total(items: list[dict]) -> float:
    return sum(i['price'] * i['qty'] for i in items)


def tax(items: list[dict]) -> float:
    return total(items) * TAX_RATE


def grand(items: list[dict]) -> float:
    return total(items) + tax(items)

